import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('passes valid input with an unlisted extra property to the executor unchanged, exactly once', async () => {
    const registry = new ToolRegistry();
    const received: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        received.push(input);
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {location: 'Berlin', units: 'metric'});

    expect({received, result: response.result}).toEqual({
      received: [{location: 'Berlin', units: 'metric'}],
      result: 'sunny',
    });
  });
});
